    "text": "\u041E\u0442\u043E\u0436\u043C\u0438 1 \u0441\u043E\u043A\u0440\u043E\u0432\u0438\u0449\u0435 \u043F\u043E \u0441\u0432\u043E\u0435\u043C\u0443 \u0432\u044B\u0431\u043E\u0440\u0443 \u0443 \u043B\u044E\u0431\u043E\u0433\u043E \u0432\u0440\u0430\u0433\u0430."
