    "type": "source",
    "name": "\u041E\u0442 \u0420\u043E\u0437\u043E\u0432\u043E\u0433\u043E \u0411\u0443\u0442\u043E\u043D\u0447\u0438\u043A\u0430",
    "school": "grass",
    "initiative": null,
    "copies": 2,
    "promo": false,
    "text": "\u041D\u0430\u043A\u0440\u0443\u0442\u0438 1 \u0436\u0438\u0437\u043D\u044C \u0437\u0430 \u043A\u0430\u0436\u0434\u044B\u0439 \u0443\u043D\u0438\u043A\u0430\u043B\u044C\u043D\u044B\u0439 \u0437\u043D\u0430\u043A \u0432 \u0442\u0432\u043E\u0451\u043C \u0437\u0430\u043A\u043B\u0438\u043D\u0430\u043D\u0438\u0438."
