    "text": "\u041D\u0430\u043D\u0435\u0441\u0438 \u0441\u0430\u043C\u043E\u043C\u0443 \u0436\u0438\u0432\u0443\u0447\u0435\u043C\u0443 \u0432\u0440\u0430\u0433\u0443 1 \u0443\u0440\u043E\u043D \u0437\u0430 \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u0436\u0438\u0432\u043E\u0433\u043E \u043A\u043E\u043B\u0434\u0443\u043D\u0430. \u0417\u0430\u0442\u0435\u043C \u0432\u043E\u0437\u044C\u043C\u0438 1 \u043A\u0430\u0440\u0442\u0443 \u0434\u043E\u0445\u043B\u043E\u0433\u043E \u043A\u043E\u043B\u0434\u0443\u043D\u0430."
