    "text": "\u0411\u0440\u043E\u0441\u044C \u043A\u0443\u0431\u0438\u043A. \u041D\u0430\u043D\u0435\u0441\u0438 \u0432\u0440\u0430\u0433\u0443 \u043F\u043E \u0442\u0432\u043E\u0435\u043C\u0443 \u0432\u044B\u0431\u043E\u0440\u0443 \u0441\u0442\u043E\u043B\u044C\u043A\u043E \u0443\u0440\u043E\u043D\u0430, \u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0432\u044B\u043F\u0430\u043B\u043E. \u041B\u044E\u0431\u043E\u0439 \u043A\u043E\u043B\u0434\u0443\u043D \u043C\u043E\u0436\u0435\u0442 \u0441\u0431\u0440\u043E\u0441\u0438\u0442\u044C 1 \u0441\u0432\u043E\u0451 \u0441\u043E\u043A\u0440\u043E\u0432\u0438\u0449\u0435, \u0447\u0442\u043E\u0431\u044B \u0442\u044B \u043F\u0435\u0440\u0435\u0431\u0440\u043E\u0441\u0438\u043B \u044D\u0442\u043E\u0442 \u043A\u0443\u0431\u0438\u043A."
