    "promo": false,
    "set": "swamp",
    "sorcery": "source",
    "text": "\u041D\u0430\u043D\u0435\u0441\u0438 2 \u0443\u0440\u043E\u043D\u0430 \u043A\u0430\u0436\u0434\u043E\u043C\u0443 \u043A\u043E\u043B\u0434\u0443\u043D\u0443, \u0432\u043A\u043B\u044E\u0447\u0430\u044F \u0441\u0435\u0431\u044F. \u041A\u043E\u043B\u0434\u0443\u043D\u0441\u0442\u0432\u043E: \u0441\u0431\u0440\u043E\u0441\u044C 2 \u0437\u0430\u0432\u043E\u0434\u0438\u043B, \u0447\u0442\u043E\u0431\u044B \u0434\u043E\u0431\u0430\u0432\u0438\u0442\u044C \u044D\u0442\u0443 \u043A\u0430\u0440\u0442\u0443 \u0441 \u0440\u0443\u043A\u0438 \u043A \u0442\u0432\u043E\u0435\u043C\u0443 \u0437\u0430\u043A\u043B\u0438\u043D\u0430\u043D\u0438\u044E."
