    "set": "swamp",
    "surprise": true,
    "text": "\u0412\u0441\u0435 \u0442\u0432\u0430\u0440\u0438, \u0447\u0435\u0439 \u044D\u0444\u0444\u0435\u043A\u0442 \u0442\u044B \u043F\u0440\u0438\u043C\u0435\u043D\u044F\u0435\u0448\u044C \u0432 \u044D\u0442\u043E\u0442 \u0445\u043E\u0434, \u043F\u043E\u043B\u0443\u0447\u0430\u044E\u0442 \u043A\u043E\u043C\u0430\u043D\u0434\u0443 \xAB\u0421\u0422\u041E\u042F\u0422\u042C!\xBB. \u041D\u0435\u0436\u0434\u0430\u043D\u0447\u0438\u043A: \u0435\u0441\u043B\u0438 \u0442\u044B \u043F\u043E\u0434\u043E\u0445 \u0434\u043E \u043F\u0440\u0438\u043C\u0435\u043D\u0435\u043D\u0438\u044F \u044D\u0444\u0444\u0435\u043A\u0442\u043E\u0432 \u044D\u0442\u043E\u0439 \u043A\u0430\u0440\u0442\u044B, \u043C\u043E\u0436\u0435\u0448\u044C \u0441\u044B\u0433\u0440\u0430\u0442\u044C \u043A\u0430\u0440\u0442\u044B \u043A\u043E\u043B\u0434\u0443\u043D\u0441\u0442\u0432 \u0441 \u0440\u0443\u043A\u0438, \u043A\u0430\u043A \u0435\u0441\u043B\u0438 \u0431\u044B \u0431\u044B\u043B \u0442\u0432\u043E\u0439 \u0445\u043E\u0434."
