    "text": "\u0412\u0440\u0430\u0433 \u043F\u043E \u0442\u0432\u043E\u0435\u043C\u0443 \u0432\u044B\u0431\u043E\u0440\u0443 \u043C\u043E\u0436\u0435\u0442 \u043E\u0442\u0434\u0430\u0442\u044C \u0442\u0435\u0431\u0435 1 \u0441\u0432\u043E\u044E \u0442\u0432\u0430\u0440\u044C, \u043D\u0430\u0445\u043E\u0434\u044F\u0449\u0443\u044E\u0441\u044F \u0432 \u0438\u0433\u0440\u0435. \u0415\u0441\u043B\u0438 \u043E\u043D \u044D\u0442\u043E\u0433\u043E \u043D\u0435 \u0441\u0434\u0435\u043B\u0430\u0435\u0442, \u0442\u043E \u0434\u043E\u043B\u0436\u0435\u043D \u0441\u0431\u0440\u043E\u0441\u0438\u0442\u044C \u0432\u0441\u0435\u0445 \u0437\u0430\u043A\u0440\u044B\u0442\u044B\u0445 \u0437\u0430\u0432\u043E\u0434\u0438\u043B \u0438 \u0432\u0441\u0435 \u0437\u0430\u043A\u0440\u044B\u0442\u044B\u0435 \u043D\u0430\u0432\u043E\u0440\u043E\u0442\u044B \u0438\u0437 \u0441\u0432\u043E\u0435\u0433\u043E \u0437\u0430\u043A\u043B\u0438\u043D\u0430\u043D\u0438\u044F."
