    "text": "\u0411\u0440\u043E\u0441\u044C \u043A\u0443\u0431\u0438\u043A. \u041A\u0430\u0436\u0434\u044B\u0439 \u043A\u043E\u043B\u0434\u0443\u043D (\u0432\u043A\u043B\u044E\u0447\u0430\u044F \u0442\u0435\u0431\u044F) \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u0441\u0442\u043E\u043B\u044C\u043A\u043E \u0443\u0440\u043E\u043D\u0430, \u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0432\u044B\u043F\u0430\u043B\u043E. \u041F\u043E\u0441\u043B\u0435 \u0431\u0440\u043E\u0441\u043A\u0430 \u043B\u044E\u0431\u043E\u0439 \u043A\u043E\u043B\u0434\u0443\u043D \u043C\u043E\u0436\u0435\u0442 \u0441\u0431\u0440\u043E\u0441\u0438\u0442\u044C 1 \u0441\u0432\u043E\u0451 \u0441\u043E\u043A\u0440\u043E\u0432\u0438\u0449\u0435, \u0447\u0442\u043E\u0431\u044B \u043D\u0435 \u043F\u043E\u043B\u0443\u0447\u0430\u0442\u044C \u0443\u0440\u043E\u043D \u043E\u0442 \u044D\u0442\u043E\u0433\u043E \u044D\u0444\u0444\u0435\u043A\u0442\u0430."
