    "name": "\u041E\u0442 \u0425\u0438\u043F\u0441\u0442\u0435\u0440\u0441\u043A\u0438\u0445 \u0445\u0438\u043F\u043F\u0438",
    "school": "fire",
    "initiative": null,
    "copies": 2,
    "promo": false,
    "set": "swamp",
    "text": "\u041D\u0430\u043D\u0435\u0441\u0438 \u043E\u0434\u043D\u043E\u043C\u0443 \u0432\u0440\u0430\u0433\u0443 \u0436\u0438\u0432\u0443\u0447\u0435\u0435 \u0442\u0435\u0431\u044F 1 \u0443\u0440\u043E\u043D \u0437\u0430 \u043A\u0430\u0436\u0434\u0443\u044E \u0442\u0432\u0430\u0440\u044C \u0438 \u043A\u0430\u0436\u0434\u0443\u044E \u0437\u0430\u043A\u0440\u044B\u0442\u0443\u044E \u043A\u0430\u0440\u0442\u0443 \u043F\u0435\u0440\u0435\u0434 \u043D\u0438\u043C."
