    "promo": false,
    "set": "swamp",
    "overdose": true,
    "text": "\u041E\u0442\u043E\u0436\u043C\u0438 1 \u0442\u0432\u0430\u0440\u044C \u0443 \u0432\u0440\u0430\u0433\u0430 \u043F\u043E \u0442\u0432\u043E\u0435\u043C\u0443 \u0432\u044B\u0431\u043E\u0440\u0443. \u041F\u0435\u0440\u0435\u0436\u043E\u0440: \u0435\u0441\u043B\u0438 \u0432 \u0442\u0432\u043E\u0451\u043C \u0437\u0430\u043A\u043B\u0438\u043D\u0430\u043D\u0438\u0438 4 \u0443\u043D\u0438\u043A\u0430\u043B\u044C\u043D\u044B\u0445 \u0437\u043D\u0430\u043A\u0430 \u0438\u043B\u0438 \u0431\u043E\u043B\u044C\u0448\u0435, \u043F\u0440\u0438\u043C\u0435\u043D\u0438 \u044D\u0444\u0444\u0435\u043A\u0442 \u044D\u0442\u043E\u0439 \u043A\u0430\u0440\u0442\u044B \u0435\u0449\u0451 \u0440\u0430\u0437."
