    "text": "\u0412\u043E\u0437\u044C\u043C\u0438 \u043D\u0430 \u0440\u0443\u043A\u0443 \u043A\u0430\u0440\u0442\u0443 \u0438\u0437 \u043A\u043E\u043B\u043E\u0434\u044B \u0437\u0430\u043A\u043B\u0438\u043D\u0430\u043D\u0438\u0439 \u0438 \u043F\u043E\u043A\u0430\u0436\u0438 \u0435\u0451 \u0432\u0441\u0435\u043C. \u041D\u0430\u043D\u0435\u0441\u0438 \u0441\u0430\u043C\u043E\u043C\u0443 \u0436\u0438\u0432\u0443\u0447\u0435\u043C\u0443 \u0432\u0440\u0430\u0433\u0443 2 \u0443\u0440\u043E\u043D\u0430 \u0437\u0430 \u043A\u0430\u0436\u0434\u044B\u0439 \u0437\u043D\u0430\u043A \u0432 \u0442\u0432\u043E\u0451\u043C \u0437\u0430\u043A\u043B\u0438\u043D\u0430\u043D\u0438\u0438, \u043A\u043E\u0442\u043E\u0440\u044B\u0439 \u0441\u043E\u0432\u043F\u0430\u0434\u0430\u0435\u0442 \u0441\u043E \u0437\u043D\u0430\u043A\u043E\u043C \u0432\u0437\u044F\u0442\u043E\u0439 \u043A\u0430\u0440\u0442\u044B."
