    "type": "quality",
    "name": "\u0414\u0443\u0448\u043D\u043E\u0432\u0430\u0442\u044B\u0439",
    "school": "dark",
    "initiative": null,
    "copies": 2,
    "promo": false,
    "set": "castle",
    "text": "\u041D\u0430\u043D\u0435\u0441\u0438 1 \u0443\u0440\u043E\u043D \u043A\u0430\u0436\u0434\u043E\u043C\u0443 \u0432\u0440\u0430\u0433\u0443. \u0421\u043B\u0435\u0439 1 \u043B\u0438\u0442\u0440 \u043A\u0440\u043E\u0432\u0438: \u0432\u044B\u0431\u0435\u0440\u0438 \u0432\u0440\u0430\u0433\u0430. \u041E\u043D \u043E\u0442\u0445\u0432\u0430\u0442\u044B\u0432\u0430\u0435\u0442 \u0441\u0442\u043E\u043B\u044C\u043A\u043E \u0443\u0440\u043E\u043D\u0430, \u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0443 \u0442\u0435\u0431\u044F \u043B\u0438\u0442\u0440\u043E\u0432 \u043A\u0440\u043E\u0432\u0438. \u0410 \u0442\u044B \u043E\u0442\u0445\u0432\u0430\u0442\u044B\u0432\u0430\u0435\u0448\u044C \u0441\u0442\u043E\u043B\u044C\u043A\u043E \u0443\u0440\u043E\u043D\u0430, \u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0443 \u043D\u0435\u0433\u043E \u043B\u0438\u0442\u0440\u043E\u0432 \u043A\u0440\u043E\u0432\u0438."
