    "text": "\u0421\u0431\u0440\u043E\u0441\u044C \u0441 \u0440\u0443\u043A\u0438 \u043B\u044E\u0431\u043E\u0435 \u0447\u0438\u0441\u043B\u043E \u043A\u0430\u0440\u0442 \u043E\u0434\u043D\u043E\u0433\u043E \u0442\u0438\u043F\u0430 (\u0437\u0430\u0432\u043E\u0434\u0438\u043B\u044B, \u043D\u0430\u0432\u043E\u0440\u043E\u0442\u044B, \u043F\u0440\u0438\u0445\u043E\u0434\u044B). \u041D\u0430\u043D\u0435\u0441\u0438 \u0432\u0440\u0430\u0433\u0443 \u043F\u043E \u0442\u0432\u043E\u0435\u043C\u0443 \u0432\u044B\u0431\u043E\u0440\u0443 \u0441\u0442\u043E\u043B\u044C\u043A\u043E \u0443\u0440\u043E\u043D\u0430, \u0441\u043A\u043E\u043B\u044C\u043A\u043E \u043A\u0430\u0440\u0442 \u0441\u0431\u0440\u043E\u0441\u0438\u043B. \u0421\u043B\u0435\u0439 4 \u043B\u0438\u0442\u0440\u0430 \u043A\u0440\u043E\u0432\u0438: \u0443\u0434\u0432\u043E\u0439 \u043D\u0430\u043D\u043E\u0441\u0438\u043C\u044B\u0439 \u0443\u0440\u043E\u043D."
