    "type": "source",
    "name": "\u041E\u0442 \u041F\u043E\u043F\u043B\u043E\u0448\u0430\u0440\u043A\u0438",
    "school": "hex",
    "initiative": null,
    "copies": 2,
    "promo": false,
    "set": "castle",
    "text": "\u041A\u0430\u0436\u0434\u044B\u0439 \u0432\u0440\u0430\u0433, \u0443\u0436\u0435 \u0441\u0445\u043E\u0434\u0438\u0432\u0448\u0438\u0439 \u0432 \u044D\u0442\u043E\u043C \u0440\u0430\u0443\u043D\u0434\u0435, \u0441\u0434\u0430\u0451\u0442 \u0442\u0435\u0431\u0435 1 \u043B\u0438\u0442\u0440 \u043A\u0440\u043E\u0432\u0438. \u041A\u0430\u0436\u0434\u044B\u0439 \u0432\u0440\u0430\u0433, \u043A\u043E\u0442\u043E\u0440\u044B\u0439 \u0435\u0449\u0451 \u043D\u0435 \u0445\u043E\u0434\u0438\u043B, \u043E\u0442\u0445\u0432\u0430\u0442\u044B\u0432\u0430\u0435\u0442 2 \u0443\u0440\u043E\u043D\u0430."
