    "copies": 2,
    "promo": false,
    "set": "school",
    "text": "\u041F\u043E\u043C\u0435\u043D\u044F\u0439\u0441\u044F \u0441\u043E\u0446\u0438\u0430\u043B\u044C\u043D\u044B\u043C \u0441\u0442\u0430\u0442\u0443\u0441\u043E\u043C \u0441 \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u044B\u043C \u0432\u0440\u0430\u0433\u043E\u043C. \u0415\u0441\u043B\u0438 \u0442\u0432\u043E\u0439 \u0441\u043E\u0446\u0438\u0430\u043B\u044C\u043D\u044B\u0439 \u0441\u0442\u0430\u0442\u0443\u0441 \u043E\u0442 \u044D\u0442\u043E\u0433\u043E \u0441\u043D\u0438\u0437\u0438\u043B\u0441\u044F, \u043D\u0430\u043D\u0435\u0441\u0438 \u044D\u0442\u043E\u043C\u0443 \u0432\u0440\u0430\u0433\u0443 4 \u0443\u0440\u043E\u043D\u0430. \u0415\u0441\u043B\u0438 \u043D\u0435\u0442, \u043D\u0430\u043D\u0435\u0441\u0438 \u0435\u043C\u0443 2 \u0443\u0440\u043E\u043D\u0430."
