    "text": "\u041F\u0440\u044F\u043C\u043E \u0441\u0435\u0439\u0447\u0430\u0441: \u0432\u043E\u0437\u044C\u043C\u0438 8 \u043A\u0430\u0440\u0442. \u0418\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0439 \u0442\u043E\u043B\u044C\u043A\u043E \u044D\u0442\u0438 8 \u043A\u0430\u0440\u0442, \u0447\u0442\u043E\u0431\u044B \u043D\u0435\u043C\u0435\u0434\u043B\u0435\u043D\u043D\u043E \u0441\u044B\u0433\u0440\u0430\u0442\u044C \u0432\u0441\u0435 \u043A\u043E\u043B\u0434\u0443\u043D\u0441\u0442\u0432\u0430 (\u0435\u0441\u043B\u0438 \u0432\u043E\u0437\u043C\u043E\u0436\u043D\u043E) \u0438 \u043F\u0440\u0438\u043C\u0435\u043D\u0438\u0442\u044C \u0438\u0445 \u044D\u0444\u0444\u0435\u043A\u0442\u044B, \u043F\u043E\u0441\u043B\u0435 \u0447\u0435\u0433\u043E \u0441\u0431\u0440\u043E\u0441\u044C \u0432\u0441\u0435 \u043E\u0441\u0442\u0430\u0432\u0448\u0438\u0435\u0441\u044F.",
