    "text": "\u041F\u0440\u044F\u043C\u043E \u0441\u0435\u0439\u0447\u0430\u0441: \u0437\u0430\u0445\u0432\u0430\u0442\u0438 \u0437\u0430\u043C\u043E\u043A. \u0415\u0441\u043B\u0438 \u0432 \u043A\u043E\u043D\u0446\u0435 \u0440\u0430\u0443\u043D\u0434\u0430 \u0437\u0430\u043C\u043E\u043A \u0443 \u0442\u0435\u0431\u044F \u0438 \u0442\u044B \u043C\u0451\u0440\u0442\u0432, \u043F\u043E\u043B\u0443\u0447\u0438 4 \u043B\u0438\u0442\u0440\u0430 \u043A\u0440\u043E\u0432\u0438 \u0432\u043C\u0435\u0441\u0442\u043E 1.",
