    "text": "\u0412 \u043D\u0430\u0447\u0430\u043B\u0435 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0439 \u0438\u0433\u0440\u044B \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0439 \u043A\u0430\u0440\u0442\u044B \u0438\u0437 \u043A\u043E\u043B\u043E\u0434\u044B \u0437\u0430\u043A\u043B\u0438\u043D\u0430\u043D\u0438\u0439, \u043F\u043E\u043A\u0430 \u043D\u0435 \u043D\u0430\u0439\u0434\u0451\u0448\u044C \u0442\u0432\u0430\u0440\u044C. \u0422\u044B \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0448\u044C \u0438\u0433\u0440\u0443 \u0441 \u044D\u0442\u043E\u0439 \u0442\u0432\u0430\u0440\u044C\u044E \u0432 \u0438\u0433\u0440\u0435. \u0421\u0431\u0440\u043E\u0441\u044C \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u043E\u0442\u043A\u0440\u044B\u0442\u044B\u0435.",
    "set": "castle"
