    "text": "\u0412 \u043D\u0430\u0447\u0430\u043B\u0435 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0439 \u0438\u0433\u0440\u044B \u043D\u0430 \u0440\u0443\u043A\u0435 \u043A\u043E\u043B\u0434\u0443\u043D\u0430, \u043A\u043E\u0442\u043E\u0440\u044B\u0439 \u043F\u043E\u043B\u0443\u0447\u0438\u0442 \u0432 \u0442\u0435\u043A\u0443\u0449\u0435\u0439 \u0438\u0433\u0440\u0435 \u043C\u0435\u0434\u0430\u043B\u044C \u043D\u0435\u0434\u043E\u0431\u0438\u0442\u043E\u0433\u043E \u043A\u043E\u043B\u0434\u0443\u043D\u0430, \u0431\u0443\u0434\u0435\u0442 \u043D\u0430 2 \u043A\u0430\u0440\u0442\u044B \u043C\u0435\u043D\u044C\u0448\u0435.",
