    "text": "\u041F\u0435\u0440\u0435\u0434 \u0442\u0435\u043C \u043A\u0430\u043A \u043F\u0440\u0438\u043C\u0435\u043D\u0438\u0442\u044C \u044D\u0444\u0444\u0435\u043A\u0442\u044B \u0441\u0432\u043E\u0435\u0433\u043E \u043F\u0435\u0440\u0432\u043E\u0433\u043E \u0437\u0430\u043A\u043B\u0438\u043D\u0430\u043D\u0438\u044F \u0432 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0439 \u0438\u0433\u0440\u0435, \u0434\u043E\u0431\u0430\u0432\u044C \u043A \u043D\u0435\u043C\u0443 \u0432\u0435\u0440\u0445\u043D\u044E\u044E \u043A\u0430\u0440\u0442\u0443 \u0438\u0437 \u043A\u043E\u043B\u043E\u0434\u044B \u0437\u0430\u043A\u043B\u0438\u043D\u0430\u043D\u0438\u0439. \u0415\u0441\u043B\u0438 \u044D\u0442\u043E \xAB\u0428\u0430\u043B\u044C\u043D\u0430\u044F \u043C\u0430\u0433\u0438\u044F\xBB, \u0432\u043E\u0437\u044C\u043C\u0438 \u0435\u0451 \u043D\u0430 \u0440\u0443\u043A\u0443 \u0438 \u0434\u043E\u0431\u0430\u0432\u044C \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0443\u044E \u043A\u0430\u0440\u0442\u0443.",
