    "text": "\u041F\u0440\u044F\u043C\u043E \u0441\u0435\u0439\u0447\u0430\u0441: \u043F\u043E\u043B\u0443\u0447\u0438 2 \u043B\u0438\u0442\u0440\u0430 \u043A\u0440\u043E\u0432\u0438. \u0415\u0441\u043B\u0438 \u0442\u044B \u0431\u044B\u043B \u043F\u0435\u0440\u0432\u044B\u0439, \u043A\u043E\u0433\u043E \u0443\u0431\u0438\u043B\u0438 \u0432 \u0442\u0435\u043A\u0443\u0449\u0435\u0439 \u0438\u0433\u0440\u0435, \u043F\u043E\u043B\u0443\u0447\u0438 \u0435\u0449\u0451 2 \u043B\u0438\u0442\u0440\u0430.",
