    "text": "\u0414\u0435\u0440\u0436\u0438 \u044D\u0442\u0443 \u043A\u0430\u0440\u0442\u0443 \u043F\u0435\u0440\u0435\u0434 \u0441\u043E\u0431\u043E\u0439, \u043F\u043E\u043A\u0430 \u043D\u0435 \u0441\u0434\u0435\u043B\u0430\u0435\u0448\u044C \u043C\u043E\u0433\u0443\u0447\u0438\u0439 \u0431\u0440\u043E\u0441\u043E\u043A \u043F\u043E \u043A\u0430\u0440\u0442\u0435 \u0442\u0432\u0430\u0440\u0438. \u0414\u043E\u0431\u0430\u0432\u044C \u043A \u044D\u0442\u043E\u043C\u0443 \u0431\u0440\u043E\u0441\u043A\u0443 1 \u043A\u0443\u0431\u0438\u043A.",
