    "text": "\u041F\u0440\u044F\u043C\u043E \u0441\u0435\u0439\u0447\u0430\u0441: \u0432\u043E\u0437\u044C\u043C\u0438 \u0435\u0449\u0451 2 \u043A\u0430\u0440\u0442\u044B \u0434\u043E\u0445\u043B\u044B\u0445 \u043A\u043E\u043B\u0434\u0443\u043D\u043E\u0432.",
