    "text": "\u0412\u043E \u0432\u0440\u0435\u043C\u044F \u043E\u0434\u043D\u043E\u0433\u043E \u0438\u0437 \u0441\u0432\u043E\u0438\u0445 \u0445\u043E\u0434\u043E\u0432 \u0432 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0439 \u0438\u0433\u0440\u0435 \u0432\u044B\u0431\u0435\u0440\u0438 \u0437\u043D\u0430\u043A. \u0414\u043E\u0431\u0430\u0432\u044C \u043E\u0434\u0438\u043D \u043A\u0443\u0431\u0438\u043A \u043A \u043A\u0430\u0436\u0434\u043E\u043C\u0443 \u0441\u0432\u043E\u0435\u043C\u0443 \u043C\u043E\u0433\u0443\u0447\u0435\u043C\u0443 \u0431\u0440\u043E\u0441\u043A\u0443 \u0441 \u044D\u0442\u0438\u043C \u0437\u043D\u0430\u043A\u043E\u043C \u0432 \u044D\u0442\u043E\u043C \u0445\u043E\u0434\u0443.",
