    "name": "\u041F\u043E\u0442\u0440\u0430\u0447\u0435\u043D",
    "text": "\u0412 \u043D\u0430\u0447\u0430\u043B\u0435 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0439 \u0438\u0433\u0440\u044B \u0432\u043E\u0437\u044C\u043C\u0438 1 \u0441\u043E\u043A\u0440\u043E\u0432\u0438\u0449\u0435.",
