      if (!c) continue;
      q.spell = q.spell.filter((x) => x !== c);
      log(e.s, `${e.p.name} \u043E\u0442\u0436\u0438\u043C\u0430\u0435\u0442 \u043F\u0440\u0438\u0445\u043E\u0434 \u0443 ${q.name}.`);
