    if (t === 2 && q?.alive && q.treasures.length) {
      const tr = chooseTreasure(e, e.p, q, `\u041A\u0430\u043A\u043E\u0435 \u0441\u043E\u043A\u0440\u043E\u0432\u0438\u0449\u0435 \u0441\u0431\u0440\u0430\u0441\u044B\u0432\u0430\u0435\u0442 ${q.name}?`);
      loseTreasure(e.s, q, tr);
      log(e.s, `${q.name} \u0441\u0431\u0440\u0430\u0441\u044B\u0432\u0430\u0435\u0442 \u0441\u043E\u043A\u0440\u043E\u0432\u0438\u0449\u0435.`);
    }
